fn hash(seed: i32) -> i32 {
    let mut h: i32 = seed * 747796405 + 2891336453;
    h = (h >> 16) ^ h;
    if h < 0 { h = 0 - h; }
    h
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, 0);
        host::display::state_set(6, 0);
        host::display::state_set(7, 0);
        host::display::state_set(9, 0);
    }
    let down: i32 = host::display::pointer_down();
    let tap: bool = down == 1 && host::display::state_get(8) == 0;
    host::display::state_set(8, down);
    let phase: i32 = host::display::state_get(1);
    let mine: i32 = host::display::state_get(6);
    let ai: i32 = host::display::state_get(7);
    if phase == 0 {
        host::display::clear(0x181410);
        host::display::draw_string(140, 140, "QUICK DRAW", 0xffcc66, 3);
        host::display::draw_string(110, 200, "FIRST TO 3 ROUNDS", 0x808080, 2);
        host::display::draw_number(180, 250, mine, 0x00ff88, 4);
        host::display::draw_string(240, 256, "VS", 0x808080, 2);
        host::display::draw_number(300, 250, ai, 0xff4040, 4);
        host::display::draw_string(130, 340, "TAP TO FACE OFF", 0xffffff, 2);
        if tap {
            let rnd: i32 = host::display::state_get(9) + 1;
            host::display::state_set(9, rnd);
            host::display::state_set(3, 40 + hash(rnd) % 80);
            host::display::state_set(4, 16 + hash(rnd * 3) % 22);
            host::display::state_set(2, 0);
            host::display::state_set(1, 1);
        }
    } else if phase == 1 {
        host::display::clear(0x401810);
        host::display::draw_string(130, 200, "STEADY...", 0xff9070, 4);
        let timer: i32 = host::display::state_get(2) + 1;
        host::display::state_set(2, timer);
        if tap {
            host::display::state_set(7, ai + 1);
            host::display::state_set(10, 0);
            host::display::state_set(11, 70);
            host::display::state_set(1, 3);
        } else if timer >= host::display::state_get(3) {
            host::audio::tone(1046, 100, 1);
            host::display::state_set(5, 0);
            host::display::state_set(1, 2);
        }
    } else if phase == 2 {
        host::display::clear(0x104018);
        host::display::draw_string(160, 190, "DRAW!", 0xffffff, 6);
        let dtimer: i32 = host::display::state_get(5) + 1;
        host::display::state_set(5, dtimer);
        if tap {
            host::display::state_set(6, mine + 1);
            host::display::state_set(10, 1);
            host::display::state_set(11, 70);
            host::display::state_set(1, 3);
        } else if dtimer >= host::display::state_get(4) {
            host::display::state_set(7, ai + 1);
            host::display::state_set(10, 0);
            host::display::state_set(11, 70);
            host::display::state_set(1, 3);
        }
    } else {
        host::display::clear(0x101018);
        if host::display::state_get(10) == 1 {
            host::display::draw_string(110, 200, "YOU FIRED FIRST", 0x00ff88, 3);
        } else {
            host::display::draw_string(120, 200, "CPU TAKES IT", 0xff4040, 3);
        }
        host::display::draw_number(180, 260, mine, 0x00ff88, 4);
        host::display::draw_number(300, 260, ai, 0xff4040, 4);
        let rt: i32 = host::display::state_get(11) - 1;
        host::display::state_set(11, rt);
        if rt <= 0 {
            if mine >= 3 || ai >= 3 {
                host::display::state_set(1, 4);
            } else {
                host::display::state_set(1, 0);
            }
        }
    }
    if phase == 4 {
        host::display::clear(0x101018);
        if mine >= 3 {
            host::display::draw_string(90, 190, "YOU WIN THE DUEL", 0x00ff88, 3);
        } else {
            host::display::draw_string(90, 190, "CPU WINS THE DUEL", 0xff4040, 3);
        }
        host::display::draw_string(130, 260, "TAP FOR A REMATCH", 0x808080, 2);
        if tap { host::display::state_set(0, 0); }
    }
    host::display::present();
}
